// Temporary helper: run a command on server .215 via ssh2, reusing the
// platform's own credential approach (decrypt server.rootPasswordEnc).
// Usage: node nexis-remote.mjs '<remote command>'   (command also via stdin if arg is "-")
import { PrismaClient } from "@prisma/client";
import { Client } from "ssh2";
import { createDecipheriv, scryptSync } from "node:crypto";
import { readFileSync } from "node:fs";

// load .env minimally
for (const line of readFileSync("/opt/nxeon/.env", "utf8").split("\n")) {
  const m = line.match(/^([A-Z0-9_]+)=(.*)$/);
  if (m && !process.env[m[1]]) process.env[m[1]] = m[2].replace(/^"(.*)"$/, "$1");
}

function deriveKey() {
  return scryptSync(process.env.AUTH_SECRET, "nxeon-byok", 32);
}
function decryptSecret(enc) {
  if (!enc) return null;
  try {
    const [ivB64, tagB64, dataB64] = enc.split(":");
    if (!ivB64 || !tagB64 || !dataB64) return null;
    const d = createDecipheriv("aes-256-gcm", deriveKey(), Buffer.from(ivB64, "base64"));
    d.setAuthTag(Buffer.from(tagB64, "base64"));
    return Buffer.concat([d.update(Buffer.from(dataB64, "base64")), d.final()]).toString("utf8");
  } catch { return null; }
}

const SERVER_ID = "cmsecmdps0001hlp27ai6mr7c";
const EXPECT_HOST = "51.79.226.215";

const cmd = process.argv[2] === "-" ? readFileSync(0, "utf8") : process.argv[2];
if (!cmd) { console.error("no command"); process.exit(2); }

const prisma = new PrismaClient();
const server = await prisma.server.findUnique({
  where: { id: SERVER_ID },
  include: { dedicatedIp: true },
});
await prisma.$disconnect();
if (!server) { console.error("server not found"); process.exit(2); }

const dedicated = !!server.dedicatedIp;
const host = dedicated ? server.dedicatedIp.address : process.env.PUBLIC_IP;
const port = dedicated ? 22 : server.sshPort;
const password = decryptSecret(server.rootPasswordEnc) ?? server.rootPassword;
if (!password) { console.error("no root password"); process.exit(2); }

const conn = new Client();
conn.on("ready", () => {
  // ASSERT hostname/IP before running the real command.
  conn.exec("hostname -I; hostname", (err, s) => {
    if (err) { console.error(err.message); conn.end(); process.exit(1); }
    let out = "";
    s.on("data", (d) => (out += d)).stderr.on("data", () => {});
    s.on("close", () => {
      if (!out.includes(EXPECT_HOST)) {
        console.error(`IP ASSERT FAILED — expected ${EXPECT_HOST}, got: ${out.trim()}`);
        conn.end(); process.exit(3);
      }
      // run the real command
      conn.exec(cmd, (e2, s2) => {
        if (e2) { console.error(e2.message); conn.end(); process.exit(1); }
        let code = null;
        s2.on("data", (d) => process.stdout.write(d));
        s2.stderr.on("data", (d) => process.stderr.write(d));
        s2.on("close", (c) => { code = c; conn.end(); process.exit(code ?? 0); });
      });
    });
  });
}).on("error", (e) => { console.error("SSH error:", e.message); process.exit(1); })
  .connect({ host, port, username: "root", password, readyTimeout: 20000 });

